import re as _re
from urllib.parse import quote_plus

def en_query(name):
    base = next((en for ru, en in EN if ru.lower() in name.lower()), "")
    tr = {"мм":"mm","Вт":"W","кВт":"kW","кВА":"kVA","т":"ton","л":"L","м":"m","А":"A","В":"V","Н·м":"Nm","Дж":"J","бар":"bar"}
    parts = []
    for num, unit in _re.findall(r"(\d+(?:/\d+)?(?:[,.]\d+)?)\s?(мм|кВт|кВА|Вт|Н·м|Дж|бар|т|л|м|А|В|\")(?=[\s,)]|$)", name):
        s = num.replace(",", ".") + ("\"" if unit == "\"" else " " + tr[unit])
        if s not in base and s not in parts: parts.append(s)
    models = [m for m in _re.findall(r"\b[A-Z]{1,3}\d{3,5}\b", name) if m not in base]
    return " ".join([base] + models + parts).strip() or name


def sources(name):
    q = en_query(name)
    return {"en_query": q,
            "alibaba": "https://www.alibaba.com/trade/search?SearchText=" + quote_plus(q),
            "made_in_china": "https://www.made-in-china.com/products-search/hot-china-products/" + "_".join(_re.findall(r"[A-Za-z0-9.]+", q)) + ".html"}


def price(fob):
    p = fob * RATE * MARKUP
    step = 1000 if p < 100_000 else 5000 if p < 1_000_000 else 10000 if p < 10_000_000 else 50000
    return int(math.ceil(p / step) * step)


def desc(name, purpose):
    return (f"{name}. {purpose}\n\n"
            "Поставка под заказ напрямую с завода в Китае. Характеристики подбираем под техническую спецификацию "
            "вашей закупки (госзакуп, Самрук-Казына, коммерческие тендеры): по мощности, исполнению, комплектации и сертификатам.\n\n"
            "Цена указана «от» за базовую комплектацию. Точная стоимость с доставкой до вашего города, растаможкой "
            "и документами — в коммерческом предложении. Доставка по Казахстану и странам СНГ.")


def load_sources():
    """data/tender_sources.txt: найденные объявления Made-in-China (фото + точная ссылка)."""
    sp = ROOT / "data" / "tender_sources.txt"
    res = {}
    if not sp.exists(): return res
    for line in sp.read_text("utf8").splitlines():
        if not line or line.startswith("#"): continue
        pid, sup, code, keys, pr = (line.split("|") + [""] * 5)[:5]
        res[pid] = {"source_url": f"https://{sup}.en.made-in-china.com/product/{code}/China-equipment.html" if sup and code else "",
                    "images": [f"https://image.made-in-china.com/2f0j00{k}/equipcn.jpg" for k in keys.split(",") if k],
                    "source_price_usd": pr}
    return res


REMOVED = {"tools", "lift", "special"}  # 24.11: решили не продавать — только основное оборудование


def main():
    srcs = load_sources()
    out = []
    for i, (cat, name, fob, purpose, specs) in enumerate(ITEMS, 1):
        if cat in REMOVED: continue
        out.append({"id": f"x{1000 + i}", "cat": cat, "name": name, "price": f"~{price(fob)}",
                    "images": [], "desc": desc(name, purpose), "specs": [list(s) for s in specs] + [["Страна производства", "Китай"]],
                    "fob_usd": fob, "rate": RATE, "markup": MARKUP, "source": "tender",
                    "src": sources(name), "source_url": "", "source_price_usd": ""})
        s = srcs.get(out[-1]["id"])
        if s: out[-1].update(s)
    ep = ROOT / "data" / "extra.json"
    old = {e["id"]: e for e in json.loads(ep.read_text("utf8"))} if ep.exists() else {}
    for e in out:
        if old.get(e["id"], {}).get("source_url"): e["source_url"] = old[e["id"]]["source_url"]
    other = [e for e in json.loads(ep.read_text("utf8")) if e.get("source") != "tender"] if ep.exists() else []
    ep.write_text(json.dumps(other + out, ensure_ascii=False, indent=1), "utf8")
    print(f"Позиций под тендеры: {len(out)}")


if __name__ == "__main__":
    main()
